package br.com.gabriel.gastocerto.domain.model

import br.com.gabriel.gastocerto.domain.rule.InvalidAmount
import kotlinx.datetime.LocalDate

/** Status of an entry: EXPECTED (generated by a recurrence, amount still to be checked) or ACTUAL. */
enum class EntryStatus { EXPECTED, ACTUAL }

/** Kind of income (RN07, RN11). */
enum class IncomeType { SALARY, ONE_OFF, INVESTMENT_SALE }

/**
 * A record of an expense or an income.
 *
 * - [accountingMonth]: month the entry belongs to in the summaries (RN01; computed by whoever creates it).
 * - [originId]: id of the recurrence that generated the EXPECTED entry; avoids duplicates on month closing (D3).
 * - RN09: [amount] is always greater than zero (`InvalidAmount`).
 * - Equality by [id] (D2).
 */
sealed class Entry(
    amount: Money,
    val date: LocalDate,
    val description: String,
    val accountingMonth: MonthYear,
    status: EntryStatus,
    val originId: String?,
    val id: String,
) {
    var amount: Money = amount
        private set

    var status: EntryStatus = status
        private set

    init {
        if (!amount.isPositive()) throw InvalidAmount(amount)
    }

    /**
     * Checks an EXPECTED entry against the month's [actualAmount] and makes it ACTUAL (RN06, RN07, RN11).
     * RN09: the actual amount must also be greater than zero. Only expected entries can be confirmed.
     */
    fun confirm(actualAmount: Money) {
        check(status == EntryStatus.EXPECTED) { "only an EXPECTED entry can be confirmed" }
        if (!actualAmount.isPositive()) throw InvalidAmount(actualAmount)
        amount = actualAmount
        status = EntryStatus.ACTUAL
    }

    final override fun equals(other: Any?): Boolean = other is Entry && other.id == id
    final override fun hashCode(): Int = id.hashCode()
}

/**
 * Money going out through a [paymentMethod].
 *
 * RN03 – may be made on behalf of a [thirdParty] who will pay it back: it counts toward the payment method
 * total and the total expenses, and is deducted from the surplus. RN05 – a foreign currency expense keeps
 * its [conversion]; [amount] is the amount in reais.
 */
open class Expense(
    amount: Money,
    date: LocalDate,
    description: String,
    accountingMonth: MonthYear,
    val paymentMethod: PaymentMethod,
    val thirdParty: Person? = null,
    val conversion: CurrencyConversion? = null,
    status: EntryStatus = EntryStatus.ACTUAL,
    originId: String? = null,
    id: String = newId(),
) : Entry(amount, date, description, accountingMonth, status, originId, id) {

    /** RN03 – the expense was made on behalf of a third party who will pay it back. */
    fun isThirdParty(): Boolean = thirdParty != null

    override fun toString(): String = "Expense($description, ${amount.cents}, $accountingMonth, ${paymentMethod.name})"
}

/**
 * RN02 – one of the installments of an [InstallmentPurchase], labeled `k/N` ([label]).
 * Keeps the [purchaseId]; the purchase has no table of its own (D5).
 */
class Installment(
    amount: Money,
    date: LocalDate,
    description: String,
    accountingMonth: MonthYear,
    paymentMethod: CreditCard,
    val purchaseId: String,
    val number: Int,
    val totalInstallments: Int,
    thirdParty: Person? = null,
    id: String = newId(),
) : Expense(amount, date, description, accountingMonth, paymentMethod, thirdParty, id = id) {

    init {
        require(number in 1..totalInstallments) { "installment $number outside 1..$totalInstallments" }
    }

    /** RN02 – `k/N` label (e.g. `2/6`). */
    fun label(): String = "$number/$totalInstallments"

    override fun toString(): String = "Installment(${label()}, $description, ${amount.cents}, $accountingMonth)"
}

/** Money coming in: salary, one-off income or investment sale (RN07, RN11). Reimbursements are not income (RN03). */
class Income(
    amount: Money,
    date: LocalDate,
    description: String,
    accountingMonth: MonthYear,
    val type: IncomeType,
    status: EntryStatus = EntryStatus.ACTUAL,
    originId: String? = null,
    id: String = newId(),
) : Entry(amount, date, description, accountingMonth, status, originId, id) {
    override fun toString(): String = "Income($description, ${amount.cents}, $accountingMonth, $type)"
}
